def compare_responses(response_a, response_b, question):
    def judge(first, second):
        prompt = f'Question: {question}\nFirst: {first}\nSecond: {second}\nWhich is better? Answer First or Second.'
        return llm.invoke(prompt)

    # Run both orderings to cancel positional bias
    result_1 = judge(response_a, response_b)
    result_2 = judge(response_b, response_a)

    votes_a = (result_1 == 'First') + (result_2 == 'Second')
    votes_b = (result_1 == 'Second') + (result_2 == 'First')
    return 'A' if votes_a > votes_b else 'B' if votes_b > votes_a else 'Tie'

