def chain_of_thought_consistent(problem, num_samples=5):
    # Self-consistency: sample multiple reasoning paths
    answers = []
    for _ in range(num_samples):
        prompt = f"""{problem}
Think step by step. After reasoning, write your final answer on the last line as:
FINAL ANSWER: <answer>"""
        response = llm.invoke(prompt, temperature=0.7)
        # Extract final answer
        for line in reversed(response.split('\n')):
            if line.startswith('FINAL ANSWER:'):
                answers.append(line.split('FINAL ANSWER:')[1].strip())
                break

    # Majority vote
    from collections import Counter
    return Counter(answers).most_common(1)[0][0]

